/* Frontier Graph - vanilla ES2020 + d3 v7, no build step.
   Sections: state, data loading, layout, rendering, interactions, drawer, filters, url-state. */
'use strict';
(() => {

// ============================================================ state
const KINDS = ['coauthor', 'shared_artifact', 'shared_repo', 'topical'];
const KIND_LABEL = { coauthor: 'Co-author', shared_artifact: 'Shared artifact', shared_repo: 'Shared repo', topical: 'Topical' };
const COLLAB = new Set(['coauthor', 'shared_artifact', 'shared_repo']);
const YEAR_MIN = 1995, YEAR_MAX = 2026;
const NEUTRAL = '#8B93A7';
const qs = new URLSearchParams(location.search);
const EMBED = qs.get('embed') === '1';
const $ = (s, r = document) => r.querySelector(s);
const $$ = (s, r = document) => [...r.querySelectorAll(s)];
const isNarrow = () => window.matchMedia('(max-width: 719px)').matches;

const S = {
  labs: [], labById: new Map(), people: [], byId: new Map(), edges: [], edgeById: new Map(),
  sel: null, selEdge: null, peek: null,
  hiLabs: new Set(), solo: null, kinds: new Set(KINDS), years: [YEAR_MIN, YEAR_MAX],
  minW: 1, hideIso: false, mech: '', view: '', cluster: true,
  k: 1, sample: false, meta: {}, visEdges: [],
};
let svg, defs, gView, gEdges, gNodes, zoom, sim, nodeSel, edgeSel;
let lastHash = '';

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const safeUrl = u => (typeof u === 'string' && /^https?:\/\//i.test(u)) ? u : null;
const link = (u, text) => { const s = safeUrl(u); return s ? `<a href="${esc(s)}" target="_blank" rel="noopener noreferrer">${esc(text)}</a>` : esc(text); };
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const colorOk = c => (typeof c === 'string' && /^#[0-9a-f]{3,8}$/i.test(c)) ? c : NEUTRAL;
const labColor = id => S.labById.get(id)?.color ?? NEUTRAL;
const labName = id => S.labById.get(id)?.label ?? id;
const tagName = t => String(t).replace(/_/g, ' ');
const yearSpan = y => (y && y[0] != null) ? (y[0] === y[1] ? `${y[0]}` : `${y[0]}–${y[1]}`) : '';
const norm = s => String(s ?? '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase();

// ============================================================ data loading
function loadScript(src) {
  return new Promise((res, rej) => {
    const s = document.createElement('script');
    s.src = src; s.onload = res; s.onerror = () => rej(new Error('could not load ' + src));
    document.head.appendChild(s);
  });
}

async function loadData() {
  const override = qs.get('data');
  if (override) {                                   // explicit location: .js (defines FRONTIER_GRAPH) or .json
    if (/\.js(\?|#|$)/i.test(override)) { window.FRONTIER_GRAPH = undefined; await loadScript(override); return window.FRONTIER_GRAPH; }
    const r = await fetch(override);
    if (!r.ok) throw new Error(`${override}: HTTP ${r.status}`);
    return r.json();
  }
  if (window.FRONTIER_GRAPH) return window.FRONTIER_GRAPH;       // from <script src="data/graph.min.js">
  if (location.protocol !== 'file:') {
    try { const r = await fetch('data/graph.json'); if (r.ok) return await r.json(); } catch (e) { /* fall through */ }
  }
  S.sample = true;                                               // nothing real available: use the bundled fixture
  await loadScript('data/graph.sample.min.js');
  return window.FRONTIER_GRAPH;
}

function prepare(d) {
  if (!d || !Array.isArray(d.people) || !Array.isArray(d.edges) || !Array.isArray(d.labs)) throw new Error('data does not match the graph contract');
  S.meta = d.meta || {};
  S.labs = d.labs.map(l => ({ ...l, color: colorOk(l.color) }));
  S.labs.forEach(l => S.labById.set(l.id, l));
  const fallbackLab = S.labById.has('other') ? 'other' : S.labs[0].id;
  S.people = d.people.map(p => {
    const n = {
      ...p, lab: S.labById.has(p.lab) ? p.lab : fallbackLab, artifact_count: +p.artifact_count || 0,
      role_families: p.role_families || [], mechanisms: p.mechanisms || [], top_artifacts: p.top_artifacts || [],
      collab: [], topo: [], vis: true,
    };
    n.r = n.artifact_count > 0 ? clamp(2.5 + 1.1 * Math.sqrt(n.artifact_count), 2.5, 13) : 2.5;
    n.mechSet = new Set(n.mechanisms.map(m => m[0]));
    n.search = norm(n.name + ' ' + (n.handle || ''));
    S.byId.set(n.id, n);
    return n;
  });
  S.edges = [];
  d.edges.forEach(e => {
    if (!S.byId.has(e.source) || !S.byId.has(e.target) || e.source === e.target) return;
    const x = { ...e, kinds: e.kinds || [], works: e.works || [], weight: +e.weight || 0 };
    x.collab = x.kinds.some(k => COLLAB.has(k));
    x.topical = x.kinds.includes('topical') && !x.collab;
    x.cross = e.cross_lab ?? (S.byId.get(e.source).lab !== S.byId.get(e.target).lab);
    x.i = S.edges.length;
    S.edges.push(x); S.edgeById.set(x.id, x);
    const a = S.byId.get(e.source), b = S.byId.get(e.target);
    (x.collab ? a.collab : a.topo).push({ e: x, o: b }); (x.collab ? b.collab : b.topo).push({ e: x, o: a });
  });
}

// ============================================================ layout
const stageSize = () => { const r = $('#stage').getBoundingClientRect(); return [r.width || 900, r.height || 600]; };
const labCenter = id => {
  const [w, h] = stageSize(), R = Math.min(w, h) / 2.6, i = Math.max(0, S.labs.findIndex(l => l.id === id));
  const a = 2 * Math.PI * i / S.labs.length - Math.PI / 2;
  return [R * Math.cos(a), R * Math.sin(a)];
};

function setClusterForces() {
  const on = S.cluster, str = on ? 0.14 : 0.03;
  sim.force('x', d3.forceX(d => on ? labCenter(d.lab)[0] : 0).strength(str))
     .force('y', d3.forceY(d => on ? labCenter(d.lab)[1] : 0).strength(str));
}

function buildSim() {
  S.people.forEach((p, i) => {                      // seed near own lab so the layout settles quickly
    const [cx, cy] = labCenter(p.lab), a = i * 2.399963, rr = 12 * Math.sqrt(i + 1);
    p.x = cx + Math.cos(a) * rr; p.y = cy + Math.sin(a) * rr;
  });
  sim = d3.forceSimulation(S.people).stop()
    .force('link', d3.forceLink(S.edges).id(d => d.id)
      .distance(e => e.collab ? Math.max(22, 66 - 9 * Math.log2(Math.max(1, e.weight))) : 110)
      .strength(e => e.collab ? 0.7 : 0.2))
    .force('charge', d3.forceManyBody().strength(-90).distanceMax(420))
    .force('collide', d3.forceCollide(d => d.r + 3.5).iterations(2));
  setClusterForces();
  sim.on('tick', positionAll);
}

function runLayout() {                              // ~300 ticks (alpha decays to alphaMin), then stay stopped
  sim.alpha(1);
  for (let i = 0; i < 300; i++) sim.tick();
  positionAll();
}

function reheat(alpha = 0.7) { sim.alpha(alpha).restart(); }

// ============================================================ rendering
function initSvg() {
  svg = d3.select('#svg');
  defs = svg.append('defs');
  gView = svg.append('g').attr('class', 'viewport');
  gEdges = gView.append('g').attr('class', 'edges');
  gNodes = gView.append('g').attr('class', 'nodes');
  zoom = d3.zoom().scaleExtent([0.15, 12]).on('zoom', ev => { gView.attr('transform', ev.transform); onZoom(ev.transform.k); });
  svg.call(zoom).on('dblclick.zoom', null);
  svg.on('click', ev => { if (ev.target === svg.node()) clearSel(); });
}

function edgeStroke(e) {
  const a = S.byId.get(e.source.id ?? e.source), b = S.byId.get(e.target.id ?? e.target);
  if (!e.collab) return null;
  if (!e.cross || a.lab === b.lab) return labColor(a.lab);
  const g = defs.append('linearGradient').attr('id', 'g' + e.i).attr('gradientUnits', 'userSpaceOnUse');
  g.append('stop').attr('offset', '0%').attr('stop-color', labColor(a.lab));
  g.append('stop').attr('offset', '100%').attr('stop-color', labColor(b.lab));
  e.grad = g.node();
  return `url(#g${e.i})`;
}

function renderGraph() {
  edgeSel = gEdges.selectAll('g.edge').data(S.edges, e => e.id).join(enter => {
    const g = enter.append('g').attr('class', e => 'edge ' + (e.collab ? 'collab' : 'topical'));
    g.append('line').attr('class', 'vis').each(function (e) {
      e.vis$ = this;
      const stroke = edgeStroke(e);
      if (stroke) this.style.stroke = stroke;
      this.style.strokeWidth = e.collab ? (1 + Math.log2(Math.max(1, e.weight))) + 'px' : '0.6px';
    });
    g.append('line').attr('class', 'hit').each(function (e) { e.hit$ = this; });
    return g;
  })
    .on('click', (ev, e) => { ev.stopPropagation(); selectEdge(e); })
    .on('mouseenter', (ev, e) => showTip(ev, `<b>${esc(e.source.name)} ↔ ${esc(e.target.name)}</b><span>${e.collab ? e.weight + ' shared work' + (e.weight === 1 ? '' : 's') : 'topical similarity ' + (e.similarity ?? '')}</span>`))
    .on('mousemove', moveTip).on('mouseleave', hideTip);

  nodeSel = gNodes.selectAll('g.node').data(S.people, d => d.id).join(enter => {
    const g = enter.append('g').attr('class', d => 'node' + (d.artifact_count === 0 ? ' hollow' : '') + (d.r >= 7 ? ' big' : ''))
      .style('--c', d => labColor(d.lab));
    g.append('circle').attr('r', d => d.r).style('fill', d => d.artifact_count ? labColor(d.lab) : null);
    g.append('text').attr('x', d => d.r + 3).text(d => d.name);
    g.each(function (d) { d.el = this; });
    return g;
  })
    .on('click', (ev, d) => { ev.stopPropagation(); select(d.id); })
    .on('mouseenter', (ev, d) => showTip(ev, `<b>${esc(d.name)}</b><span>${esc(labName(d.lab))} · ${d.artifact_count} artifact${d.artifact_count === 1 ? '' : 's'}<br>degree ${d.collab.length} collaborator${d.collab.length === 1 ? '' : 's'}${d.topo.length ? ', ' + d.topo.length + ' topical' : ''}</span>`))
    .on('mousemove', moveTip).on('mouseleave', hideTip)
    .call(d3.drag().container(gView.node())
      .on('start', (ev, d) => { if (!ev.active) sim.alphaTarget(0.25).restart(); d.fx = d.x; d.fy = d.y; hideTip(); })
      .on('drag', (ev, d) => { d.fx = ev.x; d.fy = ev.y; })
      .on('end', (ev, d) => { if (!ev.active) sim.alphaTarget(0); d.fx = d.fy = null; }));
}

function setLine(el, s, t) { el.setAttribute('x1', s.x); el.setAttribute('y1', s.y); el.setAttribute('x2', t.x); el.setAttribute('y2', t.y); }

function positionAll() {                            // runs per tick: only visible items are touched
  for (const e of S.visEdges) {
    setLine(e.vis$, e.source, e.target); setLine(e.hit$, e.source, e.target);
    if (e.grad) { e.grad.setAttribute('x1', e.source.x); e.grad.setAttribute('y1', e.source.y); e.grad.setAttribute('x2', e.target.x); e.grad.setAttribute('y2', e.target.y); }
  }
  nodeSel.attr('transform', d => `translate(${d.x},${d.y})`);
}

function onZoom(k) {
  S.k = k;
  svg.node().style.setProperty('--k', k);
  svg.classed('z1', k >= 1).classed('z2', k >= 2.5);
}

function fitView(animate = false) {
  const vis = S.people.filter(p => p.vis);
  if (!vis.length) return;
  const [w, h] = stageSize();
  const x0 = d3.min(vis, p => p.x - p.r), x1 = d3.max(vis, p => p.x + p.r), y0 = d3.min(vis, p => p.y - p.r), y1 = d3.max(vis, p => p.y + p.r);
  const k = clamp(0.92 * Math.min(w / Math.max(1, x1 - x0), h / Math.max(1, y1 - y0)), 0.15, 4);
  const t = d3.zoomIdentity.translate(w / 2, h / 2).scale(k).translate(-(x0 + x1) / 2, -(y0 + y1) / 2);
  (animate ? svg.transition().duration(600) : svg).call(zoom.transform, t);
}

function viewCenter() {                             // centre of the part of the stage not covered by the drawer
  const [w, h] = stageSize(), open = $('#drawer').classList.contains('open');
  if (!open) return [w / 2, h / 2];
  return isNarrow() ? [w / 2, h * 0.45 / 2] : [(w - 360) / 2, h / 2];
}

function zoomTo(n, animate = true) {
  const [cx, cy] = viewCenter(), k = Math.max(S.k, 1.8);
  const t = d3.zoomIdentity.translate(cx, cy).scale(k).translate(-n.x, -n.y);
  (animate ? svg.transition().duration(700) : svg).call(zoom.transform, t);
}

// tooltip
function showTip(ev, html) { const t = $('#tooltip'); t.innerHTML = html; t.hidden = false; moveTip(ev); }
function moveTip(ev) {
  const t = $('#tooltip'), r = $('#stage').getBoundingClientRect();
  let x = ev.clientX - r.left + 14, y = ev.clientY - r.top + 14;
  if (x + t.offsetWidth > r.width - 4) x = ev.clientX - r.left - t.offsetWidth - 14;
  if (y + t.offsetHeight > r.height - 4) y = ev.clientY - r.top - t.offsetHeight - 14;
  t.style.left = Math.max(4, x) + 'px'; t.style.top = Math.max(4, y) + 'px';
}
function hideTip() { $('#tooltip').hidden = true; }

// visibility: which nodes / edges survive the filters, presets and solo
function computeVisible() {
  const [y0, y1] = S.years, narrow = y0 > YEAR_MIN || y1 < YEAR_MAX;
  const needEdge = S.hideIso || S.view === 'bridges';
  S.people.forEach(p => { p.deg = 0; });
  for (const e of S.edges) {
    const a = e.source, b = e.target;
    let ok = !S.solo || (a.lab === S.solo && b.lab === S.solo);
    const ks = ok ? e.kinds.filter(k => S.kinds.has(k)) : [];
    const hasCollab = ks.some(k => COLLAB.has(k));
    if (!ks.length) ok = false;
    else if (S.view === 'bridges' && !(hasCollab && e.cross)) ok = false;
    else if (hasCollab && e.weight < S.minW) ok = false;
    else if (hasCollab && narrow && !e.works.some(w => w.year != null && w.year >= y0 && w.year <= y1)) ok = false;
    e.vis = ok;
    if (ok) { a.deg++; b.deg++; }
  }
  S.people.forEach(p => { p.vis = (!S.solo || p.lab === S.solo) && (!needEdge || p.deg > 0); });
  S.visEdges = S.edges.filter(e => e.vis);
}

function applyVisibility() {
  computeVisible();
  nodeSel.classed('hidden', d => !d.vis);
  edgeSel.classed('hidden', e => !e.vis);
  svg.classed('emph-topical', S.kinds.has('topical') && !['coauthor', 'shared_artifact', 'shared_repo'].some(k => S.kinds.has(k)));
  positionAll();
  applyHighlight();
  updateStats(); writeHash();
  $('#msg').textContent = S.people.some(p => p.vis) ? '' : 'Nothing matches the current filters.';
}

// highlight / dim: class toggles only, no data re-binding. d1 = ego dimming (0.08), d2 = lab/mechanism dimming (0.15)
function applyHighlight() {
  const sel = S.sel, se = S.selEdge, lab = S.hiLabs.size ? S.hiLabs : null, mech = S.mech;
  const ego = new Set();
  if (sel) { ego.add(sel); S.byId.get(sel).collab.concat(S.byId.get(sel).topo).forEach(a => { if (a.e.vis) ego.add(a.o.id); }); }
  if (se) { ego.add(se.source.id); ego.add(se.target.id); }
  const egoOn = !!(sel || se);
  const nodeIn = n => (!lab || lab.has(n.lab)) && (!mech || n.mechSet.has(mech));
  const dimNode = n => egoOn ? (ego.has(n.id) ? 0 : 1) : (lab || mech) ? (nodeIn(n) ? 0 : 2) : 0;
  nodeSel.each(function (n) {
    const dm = dimNode(n), c = this.classList;
    c.toggle('d1', dm === 1); c.toggle('d2', dm === 2);
    c.toggle('hl', egoOn && ego.has(n.id)); c.toggle('sel', n.id === sel);
    c.toggle('match', !egoOn && !!mech && nodeIn(n));
  });
  edgeSel.each(function (e) {
    if (!e.vis) return;
    const c = this.classList;
    let st = 0, hi = false;
    if (sel) { hi = e.source.id === sel || e.target.id === sel; st = hi ? 0 : 1; }
    else if (se) { hi = e === se; st = hi ? 0 : 1; }
    else if (lab || mech) st = (nodeIn(e.source) && nodeIn(e.target)) ? 0 : 2;
    c.toggle('d1', st === 1); c.toggle('d2', st === 2); c.toggle('hi', hi); c.toggle('sel', e === se);
  });
}

function updateStats() {
  const vp = S.people.filter(p => p.vis).length, ve = S.visEdges.length;
  const cross = S.visEdges.filter(e => e.collab && e.cross).length;
  $('#st-people').textContent = `People ${vp} / ${S.people.length}`;
  $('#st-edges').textContent = `Edges ${ve} / ${S.edges.length}`;
  $('#st-cross').textContent = `Cross-lab ${cross}`;
  $('#st-built').textContent = S.meta.corpus_built_at ? `Corpus built ${S.meta.corpus_built_at}` : '';
  $('#data-note').hidden = !S.sample;
}

// ============================================================ interactions
function select(id, opts = {}) {
  const n = S.byId.get(id);
  if (!n) return;
  if (!n.vis) resetFilters();
  S.sel = id; S.selEdge = null;
  if (S.view === 'connectors') S.view = '';
  syncPresets(); applyHighlight(); drawerPerson(n); writeHash();
  if (opts.zoom) zoomTo(n, opts.animate !== false);
}

function selectEdge(e) {
  S.sel = null; S.selEdge = e;
  if (S.view === 'connectors') S.view = '';
  syncPresets(); applyHighlight(); drawerEdge(e); writeHash();
}

function clearSel() {
  if (!S.sel && !S.selEdge && !drawer.classList.contains('open')) return;
  S.sel = null; S.selEdge = null;
  if (S.view === 'connectors') S.view = '';
  closeDrawer(); syncPresets(); applyHighlight(); writeHash();
}

const go = id => select(id, { zoom: true });

// lab chips: click = toggle highlight (multi), shift-click = solo, clicking the sole active chip resets
function buildChips() {
  const counts = d3.rollup(S.people, v => v.length, p => p.lab);
  $('#chips').innerHTML = S.labs.map(l =>
    `<button class="chip" data-lab="${esc(l.id)}" style="--c:${esc(l.color)}" aria-pressed="false" title="Click: highlight. Shift-click: show only this lab."><span class="dot"></span>${esc(l.label)} <span class="n">${counts.get(l.id) || 0}</span></button>`).join('');
  $('#chips').addEventListener('click', ev => {
    const b = ev.target.closest('[data-lab]');
    if (!b) return;
    const id = b.dataset.lab;
    if (ev.shiftKey) { if (S.solo === id) { S.solo = null; S.hiLabs.clear(); } else { S.solo = id; S.hiLabs = new Set([id]); } }
    else if (S.solo) { const same = S.solo === id; S.solo = null; S.hiLabs = same ? new Set() : new Set([id]); }
    else if (S.hiLabs.has(id)) S.hiLabs.delete(id);
    else S.hiLabs.add(id);
    syncChips(); applyVisibility();
    if (S.sel && !S.byId.get(S.sel).vis) clearSel();
  });
}

function syncChips() {
  $$('#chips .chip').forEach(b => {
    const on = S.hiLabs.has(b.dataset.lab);
    b.classList.toggle('active', on); b.setAttribute('aria-pressed', on);
    b.classList.toggle('muted', !!S.solo && !on);
  });
}

// search
function searchMatches(q) {
  q = norm(q).trim();
  if (!q) return [];
  const out = [];
  for (const p of S.people) {
    const i = p.search.indexOf(q);
    if (i < 0) continue;
    const rank = norm(p.name).startsWith(q) ? 0 : (i === 0 || p.search[i - 1] === ' ') ? 1 : 2;
    out.push([rank, -p.artifact_count, p]);
  }
  return out.sort((a, b) => a[0] - b[0] || a[1] - b[1]).slice(0, 8).map(x => x[2]);
}

function initSearch() {
  const input = $('#search'), ul = $('#suggest');
  let items = [], active = -1;
  const close = () => { ul.hidden = true; input.setAttribute('aria-expanded', 'false'); active = -1; };
  const mark = () => $$('li', ul).forEach((li, i) => li.setAttribute('aria-selected', i === active));
  const choose = p => { close(); input.value = p.name; input.blur(); select(p.id, { zoom: true }); };
  input.addEventListener('input', () => {
    items = searchMatches(input.value); active = items.length ? 0 : -1;
    ul.innerHTML = items.map(p => `<li role="option" data-id="${esc(p.id)}"><span class="dot" style="--c:${esc(labColor(p.lab))}"></span>${esc(p.name)}<span class="h">${esc(p.handle ? '@' + p.handle : labName(p.lab))}</span></li>`).join('')
      || (input.value.trim() ? '<li class="empty" style="cursor:default">No matches</li>' : '');
    ul.hidden = !ul.innerHTML; input.setAttribute('aria-expanded', String(!ul.hidden)); mark();
  });
  input.addEventListener('keydown', ev => {
    if (ev.key === 'ArrowDown' || ev.key === 'ArrowUp') {
      if (!items.length) return;
      ev.preventDefault(); active = (active + (ev.key === 'ArrowDown' ? 1 : -1) + items.length) % items.length; mark();
    } else if (ev.key === 'Enter' && items[active]) { ev.preventDefault(); choose(items[active]); }
    else if (ev.key === 'Escape') { ev.stopPropagation(); if (!ul.hidden) close(); else { input.value = ''; input.blur(); } }
  });
  ul.addEventListener('mousedown', ev => { const li = ev.target.closest('li[data-id]'); if (li) { ev.preventDefault(); choose(S.byId.get(li.dataset.id)); } });
  input.addEventListener('blur', () => setTimeout(close, 100));
}

// keyboard: "/" search, Esc clear, Left/Right walk the collaborator list in the drawer
function initKeys() {
  document.addEventListener('keydown', ev => {
    const t = ev.target, typing = /^(INPUT|TEXTAREA|SELECT)$/.test(t.tagName);
    if (ev.key === '/' && !typing && !ev.metaKey && !ev.ctrlKey) { ev.preventDefault(); $('#search').focus(); $('#search').select(); }
    else if (ev.key === 'Escape') { if (typing) t.blur(); clearSel(); }
    else if ((ev.key === 'ArrowRight' || ev.key === 'ArrowLeft') && !typing && drawer.classList.contains('open')) {
      const btns = $$('.collab .go', drawer);
      if (!btns.length) return;
      ev.preventDefault();
      const dir = ev.key === 'ArrowRight' ? 1 : -1, i = btns.indexOf(document.activeElement);
      const b = btns[i < 0 ? (dir > 0 ? 0 : btns.length - 1) : (i + dir + btns.length) % btns.length];
      b.focus(); b.scrollIntoView({ block: 'nearest' });
    }
  });
}

// ============================================================ drawer
const drawer = $('#drawer');
const openDrawer = html => {
  drawer.innerHTML = '<button class="close" data-act="close" aria-label="Close details">×</button>' + html;
  drawer.classList.add('open'); drawer.scrollTop = 0;
};
const closeDrawer = () => drawer.classList.remove('open');
const labChip = id => `<span class="lab-chip" style="--c:${esc(labColor(id))}">${esc(labName(id))}</span>`;
const plural = (n, w) => `${n} ${w}${n === 1 ? '' : 's'}`;
const workItem = w => `<li>${link(w.url, w.title || '(untitled)')}<span class="yr">${esc(w.year ?? '')}</span>${w.type ? `<span class="badge">${esc(w.type)}</span>` : ''}</li>`;
const kindBadges = e => e.kinds.map(k => `<span class="badge">${esc(KIND_LABEL[k] || k)}</span>`).join(' ');
const tagList = tags => tags.map(t => `<span class="tag">${esc(tagName(t))}</span>`).join('');

function collabRow(a) {
  const e = a.e;
  return `<li class="collab"><div class="crow"><button class="go" data-go="${esc(a.o.id)}">${esc(a.o.name)}</button>
    <span class="cmeta">${plural(e.weight, 'work')}${e.years ? ' · ' + esc(yearSpan(e.years)) : ''}</span>
    <button class="exp" data-exp aria-expanded="false" aria-label="Show shared works with ${esc(a.o.name)}">▸</button></div>
    <ul class="works" hidden><li>${kindBadges(e)}</li>${e.works.map(workItem).join('')}
    <li><button class="linkbtn" data-edge="${esc(e.id)}">Open pair view</button></li></ul></li>`;
}

function drawerPerson(n) {
  const groups = new Map();
  [...n.collab].sort((a, b) => b.e.weight - a.e.weight || a.o.name.localeCompare(b.o.name))
    .forEach(a => { if (!groups.has(a.o.lab)) groups.set(a.o.lab, []); groups.get(a.o.lab).push(a); });
  const collabs = S.labs.filter(l => groups.has(l.id)).map(l =>
    `<div class="group-h"><span class="dot" style="--c:${esc(l.color)}"></span>${esc(l.label)} (${groups.get(l.id).length})</div><ul>${groups.get(l.id).map(collabRow).join('')}</ul>`).join('');
  const topo = [...n.topo].sort((a, b) => (b.e.similarity || 0) - (a.e.similarity || 0)).map(a =>
    `<li><button class="go" data-go="${esc(a.o.id)}">${esc(a.o.name)}</button><span class="cmeta">similarity ${esc((a.e.similarity ?? 0).toFixed(2))}</span>
     <span class="cmeta" style="flex-basis:100%">${esc((a.e.shared_tags || []).map(tagName).join(', '))}</span></li>`).join('');
  openDrawer(`<h2>${n.x_url && safeUrl(n.x_url) ? link(n.x_url, n.name) : esc(n.name)}</h2>
    ${labChip(n.lab)}${n.handle ? ` <span class="yr">@${esc(n.handle)}</span>` : ''}
    <p class="facts"><b>${n.artifact_count}</b> accepted artifact${n.artifact_count === 1 ? '' : 's'}${yearSpan(n.years) ? ` · <b>${esc(yearSpan(n.years))}</b>` : ''}</p>
    ${n.role_families.length ? `<div class="tags">${n.role_families.map(r => `<span class="tag">${esc(tagName(r))}</span>`).join('')}</div>` : ''}
    ${n.mechanisms.length ? `<div class="tags">${n.mechanisms.map(m => `<span class="tag">${esc(tagName(m[0]))} <i>${esc(m[1])}</i></span>`).join('')}</div>` : ''}
    <h4>Collaborators (${n.collab.length})</h4>${collabs || '<p class="empty">No collaboration edges in the corpus.</p>'}
    <h4>Topical neighbors (${n.topo.length})</h4>${topo ? `<ul class="plain">${topo}</ul>` : '<p class="empty">None.</p>'}
    <h4>Recent work</h4>${n.top_artifacts.length ? `<ul class="plain">${n.top_artifacts.map(workItem).join('')}</ul>` : '<p class="empty">No accepted artifacts.</p>'}`);
}

function pcard(n) {
  return `<button class="pcard" style="--c:${esc(labColor(n.lab))}" data-go="${esc(n.id)}"><b>${esc(n.name)}</b><span>${esc(labName(n.lab))} · ${plural(n.artifact_count, 'artifact')}</span></button>`;
}

function drawerEdge(e) {
  const a = e.source, b = e.target;
  openDrawer(`<h2>${e.collab ? 'Collaboration' : 'Topical similarity'}</h2>
    <div class="pair">${pcard(a)}<span class="arrow">↔</span>${pcard(b)}</div>
    <div>${kindBadges(e)}${e.cross ? ' <span class="badge">cross-lab</span>' : ''}</div>
    ${e.collab ? `<p class="facts"><b>${plural(e.weight, 'shared work')}</b>${e.years ? ` · ${esc(yearSpan(e.years))}` : ''}</p>
      <h4>Shared works</h4><ul class="plain">${e.works.map(workItem).join('') || '<li class="empty">No works recorded.</li>'}</ul>` : ''}
    ${e.similarity != null ? `<p class="facts">Mechanism similarity <b>${esc(Number(e.similarity).toFixed(2))}</b> (Jaccard)</p>
      <h4>Shared tags</h4><div class="tags">${tagList(e.shared_tags || []) || '<span class="empty">none</span>'}</div>` : ''}`);
}

function drawerConnectors() {
  const rows = S.people.filter(p => p.collab.length)
    .map(p => ({ p, labs: new Set(p.collab.map(a => a.o.lab)).size, deg: p.collab.length }))
    .sort((a, b) => b.labs - a.labs || b.deg - a.deg || a.p.name.localeCompare(b.p.name)).slice(0, 20);
  openDrawer(`<h2>Top connectors</h2><p class="facts">Ranked by distinct labs among collaborators, then by number of collaborators.</p>
    <ul class="plain">${rows.map((r, i) => `<li><span class="rank">${i + 1}</span><button class="go" data-go="${esc(r.p.id)}">${esc(r.p.name)}</button>${labChip(r.p.lab)}
      <span class="cmeta" style="flex-basis:100%;padding-left:30px">${plural(r.labs, 'lab')} · ${plural(r.deg, 'collaborator')}</span></li>`).join('') || '<li class="empty">No collaboration edges.</li>'}</ul>`);
}

drawer.addEventListener('click', ev => {
  const t = ev.target;
  if (t.closest('[data-act="close"]')) return clearSel();
  const g = t.closest('[data-go]');
  if (g) return go(g.dataset.go);
  const ed = t.closest('[data-edge]');
  if (ed) return selectEdge(S.edgeById.get(ed.dataset.edge));
  const x = t.closest('[data-exp]');
  if (x) { const ul = x.closest('.collab').querySelector('.works'); ul.hidden = !ul.hidden; x.setAttribute('aria-expanded', String(!ul.hidden)); }
});
drawer.addEventListener('focusin', ev => {       // preview the focused collaborator on the canvas
  const id = ev.target.dataset?.go;
  if (nodeSel) nodeSel.classed('peek', d => d.id === id);
});
drawer.addEventListener('focusout', () => nodeSel && nodeSel.classed('peek', false));

// ============================================================ filters
function buildMechSelect() {
  const cnt = new Map();
  S.people.forEach(p => p.mechSet.forEach(t => cnt.set(t, (cnt.get(t) || 0) + 1)));
  const top = [...cnt].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0])).slice(0, 40);
  $('#mech').innerHTML = '<option value="">Any</option>' + top.map(([t, c]) => `<option value="${esc(t)}">${esc(tagName(t))} (${c})</option>`).join('');
}

function initFilters() {
  const changed = () => { syncControls(); applyVisibility(); };
  $$('[data-kind]').forEach(cb => cb.addEventListener('change', () => { cb.checked ? S.kinds.add(cb.dataset.kind) : S.kinds.delete(cb.dataset.kind); changed(); }));
  const yMin = $('#y-min'), yMax = $('#y-max');
  const years = ev => {
    let a = +yMin.value, b = +yMax.value;
    if (a > b) { if (ev.target === yMin) a = b; else b = a; }
    S.years = [a, b]; changed();
  };
  yMin.addEventListener('input', years); yMax.addEventListener('input', years);
  $('#minw').addEventListener('input', ev => { S.minW = +ev.target.value; changed(); });
  $('#iso').addEventListener('change', ev => { S.hideIso = ev.target.checked; changed(); });
  $('#mech').addEventListener('change', ev => { S.mech = ev.target.value; applyHighlight(); writeHash(); });
  $('#cluster').addEventListener('change', ev => { S.cluster = ev.target.checked; setClusterForces(); reheat(0.8); });
  const fb = $('#toggle-filters'), fbState = () => fb.setAttribute('aria-expanded', String(isNarrow() ? document.body.classList.contains('filters-open') : !document.body.classList.contains('filters-collapsed')));
  fb.addEventListener('click', () => { document.body.classList.toggle(isNarrow() ? 'filters-open' : 'filters-collapsed'); fbState(); });
  window.addEventListener('resize', fbState); fbState();
  $('#p-bridges').addEventListener('click', () => {
    S.view = S.view === 'bridges' ? '' : 'bridges';
    if (drawer.classList.contains('open') && !S.sel && !S.selEdge) closeDrawer();
    syncPresets(); applyVisibility(); fitView(true);
  });
  $('#p-connectors').addEventListener('click', () => {
    if (S.view === 'connectors') return clearSel();
    S.sel = null; S.selEdge = null; S.view = 'connectors';
    syncPresets(); applyVisibility(); drawerConnectors();
  });
  $('#p-reset').addEventListener('click', () => { resetFilters(); clearSel(); $('#search').value = ''; fitView(true); });
}

function syncPresets() {
  $('#p-bridges').setAttribute('aria-pressed', S.view === 'bridges');
  $('#p-connectors').classList.toggle('on', S.view === 'connectors');
}

function syncControls() {                          // push state into the controls (used by reset and hash load)
  $$('[data-kind]').forEach(cb => { cb.checked = S.kinds.has(cb.dataset.kind); });
  const [a, b] = S.years;
  $('#y-min').value = a; $('#y-max').value = b;
  $('#y-min').style.zIndex = a > YEAR_MAX - (YEAR_MAX - YEAR_MIN) / 2 ? 3 : 1;
  $('#years-out').textContent = `${a}–${b}`;
  $('#minw').value = S.minW; $('#minw-out').textContent = S.minW;
  $('#iso').checked = S.hideIso; $('#mech').value = S.mech; $('#cluster').checked = S.cluster;
  syncChips(); syncPresets();
}

function resetFilters() {
  S.hiLabs.clear(); S.solo = null; S.kinds = new Set(KINDS); S.years = [YEAR_MIN, YEAR_MAX];
  S.minW = 1; S.hideIso = false; S.mech = ''; S.view = '';
  if (!S.cluster) { S.cluster = true; setClusterForces(); reheat(0.8); }
  syncControls(); applyVisibility();
}

// ============================================================ url-state
function stateToHash() {
  const p = new URLSearchParams();
  if (S.sel) p.set('p', S.sel);
  if (S.hiLabs.size) p.set('labs', [...S.hiLabs].join(','));
  if (S.solo) p.set('solo', '1');
  if (S.kinds.size !== KINDS.length) p.set('kinds', KINDS.filter(k => S.kinds.has(k)).join(','));
  if (S.years[0] !== YEAR_MIN || S.years[1] !== YEAR_MAX) p.set('years', S.years.join('-'));
  if (S.view) p.set('view', S.view);
  if (S.minW > 1) p.set('w', S.minW);
  if (S.mech) p.set('mech', S.mech);
  if (S.hideIso) p.set('iso', '1');
  return p.toString().replace(/%3A/gi, ':').replace(/%2C/gi, ',');
}

function writeHash() {
  const h = stateToHash();
  if (h === lastHash) return;
  lastHash = h;
  try { history.replaceState(null, '', location.pathname + location.search + (h ? '#' + h : '')); } catch (e) { /* sandboxed */ }
}

function applyHashState() {                         // returns the person id to select, if any
  const p = new URLSearchParams(location.hash.slice(1));
  const labs = (p.get('labs') || '').split(',').filter(l => S.labById.has(l));
  S.solo = p.get('solo') === '1' && labs.length === 1 ? labs[0] : null;   // solo = one lab plus solo=1
  S.hiLabs = new Set(labs);
  S.kinds = p.has('kinds') ? new Set(p.get('kinds').split(',').filter(k => KINDS.includes(k))) : new Set(KINDS);
  const m = /^(\d{4})-(\d{4})$/.exec(p.get('years') || '');
  S.years = m ? [clamp(+m[1], YEAR_MIN, YEAR_MAX), clamp(+m[2], YEAR_MIN, YEAR_MAX)].sort((x, y) => x - y) : [YEAR_MIN, YEAR_MAX];
  S.view = ['bridges', 'connectors'].includes(p.get('view')) ? p.get('view') : '';
  S.minW = clamp(parseInt(p.get('w'), 10) || 1, 1, 10);
  const mech = p.get('mech') || '';
  S.mech = mech && $(`#mech option[value="${CSS.escape(mech)}"]`) ? mech : '';
  S.hideIso = p.get('iso') === '1';
  lastHash = location.hash.slice(1);
  return S.byId.has(p.get('p')) ? p.get('p') : null;
}

function restoreFromHash(animate) {
  const id = applyHashState();
  syncControls(); applyVisibility();
  if (id) select(id, { zoom: true, animate });
  else if (S.view === 'connectors') drawerConnectors();
  else clearSel();
}

// ============================================================ init
async function init() {
  if (EMBED) document.documentElement.classList.add('embed');
  try { prepare(await loadData()); }
  catch (e) { $('#msg').textContent = 'Could not load graph data: ' + e.message; return; }
  buildChips(); buildMechSelect(); initSvg(); buildSim(); renderGraph(); runLayout(); onZoom(1);
  initFilters(); initSearch(); initKeys();
  restoreFromHash(false);
  fitView(false);
  if (S.sel) zoomTo(S.byId.get(S.sel), false);
  window.addEventListener('hashchange', () => { if (location.hash.slice(1) !== lastHash) restoreFromHash(true); });
  window.__frontierGraph = { S, select, clearSel, reheat, get sim() { return sim; } };  // handy for debugging in the console
}
init();
})();
